targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
    if (!api.state || !api.state.articlePreview || !api.item) {
        return {
            propName: "articlePreview",
            value: []
        };
    }

    const articlePreview = api.state.articlePreview;
    const index = api.item.index;

    const newArticlePreview = articlePreview.map((item, i) => {
        if (i === index && item && item.collapsible) {
            return {
                ...item,
                collapsed: !item.collapsed
            };
        }
        return item;
    });

    return {
        propName: "articlePreview",
        value: newArticlePreview
    };
})

